import base64,zlib,os
d=""
with open("/var/www/luxe-talent/dist/dashboard.html","wb") as f: f.write(zlib.decompress(base64.b64decode(d)))
print("dashboard.html:",len(zlib.decompress(base64.b64decode(d))),"bytes")
os.system("chown apache:apache /var/www/luxe-talent/dist/dashboard.html")
print("Done!")